/// location-fields: Controlled address
private struct LocationFieldsExample0: View {
    @State private var address = MonarchLocationValue(country: "CA", region: "CA-ON", regionName: "Ontario", city: "Toronto", cityID: "ca-tor", postalCode: "")

    private let adapter = MonarchLocationAdapter(
        countries: {
            [
                MonarchLocationOption(id: "CA", label: "Canada"),
                MonarchLocationOption(id: "IN", label: "India"),
                MonarchLocationOption(id: "SG", label: "Singapore"),
                MonarchLocationOption(id: "AE", label: "United Arab Emirates"),
            ]
        },
        regions: { country in
            switch country {
            case "CA":
                MonarchLocationRegions(
                    [
                        MonarchRegion(code: "CA-BC", name: "British Columbia"),
                        MonarchRegion(code: "CA-ON", name: "Ontario"),
                        MonarchRegion(code: "CA-QC", name: "Quebec"),
                    ],
                    label: "Province"
                )
            case "IN":
                MonarchLocationRegions(
                    [
                        MonarchRegion(code: "IN-KA", name: "Karnataka"),
                        MonarchRegion(code: "IN-MH", name: "Maharashtra"),
                        MonarchRegion(code: "IN-TN", name: "Tamil Nadu"),
                    ],
                    label: "State / Union Territory"
                )
            case "AE":
                MonarchLocationRegions(
                    [MonarchRegion(code: "AE-AZ", name: "Abu Dhabi"), MonarchRegion(code: "AE-DU", name: "Dubai")],
                    label: "Emirate"
                )
            default:
                MonarchLocationRegions([], label: "Region")
            }
        },
        cities: { query in
            let all = [
                MonarchLocationCity(id: "ca-van", name: "Vancouver", region: MonarchRegion(code: "CA-BC", name: "British Columbia")),
                MonarchLocationCity(id: "ca-tor", name: "Toronto", region: MonarchRegion(code: "CA-ON", name: "Ontario")),
                MonarchLocationCity(id: "ca-ott", name: "Ottawa", region: MonarchRegion(code: "CA-ON", name: "Ontario")),
                MonarchLocationCity(id: "ca-mtl", name: "Montreal", region: MonarchRegion(code: "CA-QC", name: "Quebec")),
                MonarchLocationCity(id: "in-blr", name: "Bengaluru", region: MonarchRegion(code: "IN-KA", name: "Karnataka")),
                MonarchLocationCity(id: "in-bom", name: "Mumbai", region: MonarchRegion(code: "IN-MH", name: "Maharashtra")),
                MonarchLocationCity(id: "in-maa", name: "Chennai", region: MonarchRegion(code: "IN-TN", name: "Tamil Nadu")),
                MonarchLocationCity(id: "ae-dxb", name: "Dubai", region: MonarchRegion(code: "AE-DU", name: "Dubai")),
                MonarchLocationCity(id: "ae-auh", name: "Abu Dhabi", region: MonarchRegion(code: "AE-AZ", name: "Abu Dhabi")),
            ]
            return all.filter {
                $0.id.hasPrefix(query.country.lowercased())
                    && (query.region == nil || $0.region?.code == query.region)
                    && (query.query.isEmpty || $0.name.localizedCaseInsensitiveContains(query.query))
            }
        }
    )

    /// The value as JSON, shown under the fields as the web example does.
    private var json: String {
        func quoted(_ text: String?) -> String { text.map { "\"\($0)\"" } ?? "null" }
        return """
            {
              "country": \(quoted(address.country)),
              "region": \(quoted(address.region)),
              "regionName": \(quoted(address.regionName)),
              "city": \(quoted(address.city)),
              "cityId": \(quoted(address.cityID)),
              "postalCode": \(quoted(address.postalCode))
            }
            """
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 12) {
            MonarchLocationFields(
                "Billing address",
                value: $address,
                adapter: adapter,
                required: [.country, .city]
            )
            Text(json)
                .monarchTextStyle(.code)
        }
    }
}

