/// phone-country-select: Beside a phone number
private struct PhoneCountrySelectExample0: View {
    @State private var country: String? = "GB"
    @State private var dialCode: String? = "+44"
    @State private var number = ""

    var body: some View {
        HStack(alignment: .top, spacing: 8) {
            MonarchPhoneCountrySelect(
                "Country code",
                selection: $country,
                preferred: ["GB", "US"]
            )
            .fixedSize(horizontal: true, vertical: false)
            .onChange(of: country) { _, code in
                dialCode = code.flatMap { MonarchPhoneCountry.country(code: $0)?.dialCode }
            }
            MonarchTextField(
                "Phone number",
                text: $number,
                helper: "Saved as" + " " + (dialCode ?? "—") + " " + (number.isEmpty ? "…" : number)
            )
        }
    }
}

