/// region-select: With CountrySelect and built-in lists
private struct RegionSelectExample0: View {
    @Environment(\.monarchTheme) private var theme
    @State private var country: String? = "US"
    @State private var region: String? = nil

    var body: some View {
        VStack(alignment: .leading, spacing: theme.spacing.space3) {
            MonarchCountrySelect(
                "Country",
                selection: $country,
                countries: ["AU", "CA", "FR", "GB", "IN", "US"],
                isClearable: false
            )
            MonarchRegionSelect(
                MonarchRegionSelect.fieldLabel(for: country) ?? "Region",
                selection: $region,
                country: country,
                prompt: "",
                isClearable: false
            )
        }
        .onChange(of: country) { region = nil }
    }
}

